31	static int g_master_init_flag = 0;
32	static pthread_mutex_t master_mutex = PTHREAD_MUTEX_INITIALIZER;
33	
34	static int svm_device_open_locked(u32 devid)
35	{
36	    int ret;
37	
38	    if (dev_status[devid] != 0) {
39	        /* Support repeated open. */
40	        return DRV_ERROR_REPEATED_USERD;
41	    }
42	
43	    ret = svm_ioctl_dev_init(devid);
44	    if (ret != 0) {
45	        return ret;
46	    }
47	
48	    dev_status[devid] = 1;
49	
50	    svm_info("Open success. (devid=%u)\n", devid);
51	
52	    return DRV_ERROR_NONE;
53	}
54	
55	static void svm_device_res_recycle(u32 devid)
56	{
57	    svm_madvise_recycle(devid);
58	    svm_register_recycle(devid);
59	    svm_register_pcie_th_recycle(devid);
60	    svm_prefetch_recycle(devid);
61	    vmm_recycle(devid);
62	    (void)svm_recycle_mem_by_dev(devid);
63	}
64	
65	static int svm_device_close_locked(u32 devid)
66	{
67	    int ret;
68	
69	    if (dev_status[devid] == 0) {
70	        /* Support repeated close. */
71	        return DRV_ERROR_REPEATED_USERD;
72	    }
73	
74	    svm_occupy_pipeline();
75	    if (devid < SVM_MAX_AGENT_NUM) {
76	        svm_device_res_recycle(devid);
77	    }
78	
79	    ret = svm_ioctl_dev_uninit(devid); /* Dev uninit pre handle will recycle sub module res.  */
80	    svm_release_pipeline();
81	    if (ret != 0) {
82	        return ret;
83	    }
84	
85	    dev_status[devid] = 0;
86	
87	    svm_info("Close success. (devid=%u)\n", devid);
88	
89	    return DRV_ERROR_NONE;
90	}
91	
92	static int svm_device_open(u32 devid)
93	{
94	    int ret;
95	
96	    (void)pthread_mutex_lock(&master_mutex);
97	    ret = svm_device_open_locked(devid);
98	    (void)pthread_mutex_unlock(&master_mutex);
99	
100	    return ret;
101	}
