103	int svm_device_close(u32 devid)
104	{
105	    u32 udevid;
106	    int ret;
107	
108	    if (devid >= SVM_MAX_AGENT_NUM) {
109	        svm_err("Invalid devid. (devid=%u)\n", devid);
110	        return DRV_ERROR_INVALID_DEVICE;
111	    }
112	
113	    ret = uda_get_udevid_by_devid(devid, &udevid);
114	    if (ret != DRV_ERROR_NONE) {
115	        svm_err("Get udevid failed. (devid=%u; ret=%d)\n", devid, ret);
116	        return DRV_ERROR_PARA_ERROR;
117	    }
118	
119	    (void)pthread_mutex_lock(&master_mutex);
120	    ret = svm_device_close_locked(devid);
121	    (void)pthread_mutex_unlock(&master_mutex);
122	
123	    return ret;
124	}
