145	int svm_master_init(void)
146	{
147	    int ret = 0;
148	
149	    if (g_master_init_flag == 1) {
150	        return DRV_ERROR_NONE;
151	    }
152	
153	    (void)pthread_mutex_lock(&master_mutex);
154	    if (g_master_init_flag == 0) {
155	        ret = svm_master_init_locked();
156	        if (ret == 0) {
157	            g_master_init_flag = 1;
158	        }
159	    }
160	    (void)pthread_mutex_unlock(&master_mutex);
161	
162	    return ret;
163	}
