166	{
167	    (void)pthread_mutex_lock(&master_mutex);
168	    if (g_master_init_flag == 1) {
169	        g_master_init_flag = 0;
170	        svm_master_uninit_locked();
171	    }
172	    (void)pthread_mutex_unlock(&master_mutex);
173	}
