281	static int dev_reset_status[SVM_MAX_DEV_NUM] = {0};
282	static int svm_proc_res_backup(void)
283	{
284	    u32 devid;
285	    int ret = 0;
286	
287	    for (devid = 0; devid < SVM_MAX_DEV_NUM; devid++) {
288	        if (dev_status[devid] != 0) {
289	            ret = svm_criu_backup(devid);
290	            if (ret != 0) {
291	                return ret;
292	            }
293	        }
294	        dev_reset_status[devid] = 0;
295	    }
296	
297	    return 0;
298	}
299	
300	static int svm_close_user_dev_res(u32 devid)
301	{
302	    if (dev_reset_status[devid] == 1) {
303	        return 0;
304	    }
305	
306	    if (dev_status[devid] != 0) {
307	        int ret = svm_criu_reset(devid);
308	        if (ret != 0) {
309	            svm_err("Failed to reset device. (ret=%d; devid=%u)\n", ret, devid);
310	            return ret;
311	        }
312	
313	        dev_status[devid] = 0;
314	        if (devid == svm_get_host_devid()) {
315	            g_master_init_flag = 0;
316	        }
317	    }
318	
319	    dev_reset_status[devid] = 1;
320	    return 0;
321	}
322	
323	static int svm_close_user_res(void)
324	{
325	    u32 host_devid = svm_get_host_devid();
326	    u32 devid;
327	
328	    for (devid = 0; devid < SVM_MAX_DEV_NUM; devid++) {
329	        if (devid != host_devid) {
330	            int ret = svm_close_user_dev_res(devid);
331	            if (ret != 0) {
332	                return ret;
333	            }
334	        }
335	    }
336	
337	    return svm_close_user_dev_res(host_devid);
338	}
