340	static int svm_proc_res_restore(void)
341	{
342	    u32 host_devid = svm_get_host_devid();
343	    u32 i;
344	
345	    int ret;
346	
347	    for (i = 0; i < SVM_MAX_DEV_NUM; i++) {
348	        u32 devid = (host_devid + i) % SVM_MAX_DEV_NUM;
349	        if (dev_status[devid] != 0) {
350	            ret = svm_criu_restore(devid);
351	            if (ret != 0) {
352	                return ret;
353	            }
354	        }
355	    }
356	
357	    return 0;
358	}
