162	void *devmm_svm_map_with_flag(void *mem_map_addr, uint64_t size, uint64_t flags, int fixed_va_flag)
163	{
164	    void *mem_mapped_addr = NULL;
165	    int err;
166	    int ret;
167	
168	    mem_mapped_addr = mmap(mem_map_addr, size, PROT_READ | PROT_WRITE, (int)(MAP_SHARED | flags), g_devmm_mem_dev, 0);
169	    if (mem_mapped_addr == MAP_FAILED) {
170	        err = errno;
171	        DEVMM_RUN_INFO("Host mem goto malloc. (mapped=%p; start=%p; errno=%d; errstr=%s)\n", mem_map_addr,
172	                       mem_mapped_addr, err, strerror(err));
173	        return NULL;
174	    }
175	
176	    if ((fixed_va_flag == 1) && (mem_mapped_addr != mem_map_addr)) {
177	        (void)munmap((void *)(uintptr_t)mem_mapped_addr, size);
178	        return NULL;
179	    }
180	
181	    ret = madvise(mem_mapped_addr, size, MADV_DONTDUMP);
182	    if (ret != 0) {
183	        (void)munmap(mem_mapped_addr, size);
184	        return NULL;
185	    }
186	
187	    return mem_mapped_addr;
188	}
