296	DVresult devmm_svm_map(int side)
297	{
298	    void *mem_mapped_addr = NULL;
299	    uint32_t seg_num = DEVMM_MAX_VMA_NUM;
300	    uint32_t i;
301	    int ret;
302	
303	    (void)pthread_mutex_lock(&g_devmm_mmap_mutex);
304	
305	    ret = devmm_svm_get_mmap_para(g_mmap_segs, &seg_num);
306	    if (ret != 0) {
307	        (void)pthread_mutex_unlock(&g_devmm_mmap_mutex);
308	        DEVMM_DRV_ERR("Get mmap para error. (ret=%d)\n", ret);
309	        return ret;
310	    }
311	
312	    for (i = 0; i < seg_num; i++) {
313	        mem_mapped_addr = devmm_svm_map_by_size((void *)(uintptr_t)g_mmap_segs[i].va, g_mmap_segs[i].size);
314	        if (mem_mapped_addr == NULL) {
315	            if (devmm_is_in_host_uva_range(g_mmap_segs[i].va, g_mmap_segs[i].size)) {
316	                g_host_pin_memory_map_failed = true;
317	                continue;
318	            }
319	            devmm_svm_unmap_range(i);
320	            (void)pthread_mutex_unlock(&g_devmm_mmap_mutex);
321	            return devmm_get_svm_map_err_result(side);
322	        }
323	        if (devmm_is_in_host_uva_range(g_mmap_segs[i].va, g_mmap_segs[i].size)) {
324	            g_devmm_host_uva_start = g_mmap_segs[i].va;
325	        }
326	    }
327	
328	    g_mmap_seg_num = seg_num;
329	    (void)pthread_mutex_unlock(&g_devmm_mmap_mutex);
330	
331	    return DRV_ERROR_NONE;
332	}
